PURCHASE_NOTE = re.compile(r"Data da compra: (\d{2})/(\d{2})/(\d{4})")


def purchase_dates_from_notes(apps, schema_editor):
    """Imported card purchases wrote "Data da compra: dd/mm/aaaa." in the note: keep it as a field."""
    Transaction = apps.get_model("app", "Transaction")
    for tx in Transaction.objects.filter(account__type="credit", purchase_date__isnull=True, note__contains="Data da compra:"):
        found = PURCHASE_NOTE.search(tx.note)
        if found:
            day, month, year = (int(x) for x in found.groups())
            try:
                tx.purchase_date = datetime.date(year, month, day)
            except ValueError:
                continue
            tx.save(update_fields=["purchase_date"])


